-- The coverage file wins over the older spell lookup for the same spell.
function onInit()
  CCSyrinCatalog.spells = CCSyrinCatalog.spells or {}
  local at = {}
  for i, s in ipairs(CCSyrinCatalog.spells) do at[s.pattern] = i end
  for _, s in ipairs(spells) do
    if at[s.pattern] then
      CCSyrinCatalog.spells[at[s.pattern]] = s
    else
      table.insert(CCSyrinCatalog.spells, s)
      at[s.pattern] = #CCSyrinCatalog.spells
    end
  end
end
